  _debugCheckNoParamsWithTarget('registerHandler', target, param1, param2);
  if (target == null) {
    _debugCheckRegistration<T>(
        getItInstance, 'registerHandler', instanceName, param1, param2);
  }
  final parentObject = target ??
      getItInstance<T>(
          instanceName: instanceName, param1: param1, param2: param2);

  // Validate target type when no select function is provided
  if (select == null && parentObject is! Listenable) {
    throw ArgumentError(
        'When no select function is provided, target must be a Listenable. '
        'Got: ${parentObject.runtimeType}');
  }

  _activeWatchItState!.watchListenable<T, R>(
    parentOrListenable: parentObject,
    selector: select,
    allowObservableChange: allowObservableChange,
    handler: handler,
    executeImmediately: executeImmediately,
  );
}

